import { REDACTION_MASK } from '../constants'

/** Lists the non-empty secrets, longest first, so a secret inside another leaves no fragment. */
function orderedSecrets(secrets: ReadonlySet<string>): string[] {
  return [...secrets]
    .filter((secret) => secret.length > 0)
    .sort((left, right) => right.length - left.length)
}

/** Keys whose whole value is generated by Codebook and holds no learner text: a copy-ready continuation and a step's reference. */
const GENERATED_VALUE_KEYS: ReadonlySet<string> = new Set([
  'continueArguments',
  'reference',
])

/** Keys of generated identifiers: `id`, `key`, `hash`, `uri` and every camelCase key ending in one (`runId`, `sessionId`, `runUri`, `sourceHash`, `idempotencyKey`). */
const IDENTIFIER_KEY =
  /^(?:id|key|hash|uri)$|(?:Id|Ids|Key|Keys|Hash|Hashes|Uri|Uris)$/

/**
 * Says whether a property holds an identifier Codebook generated, which keeps its bytes when learner secrets are masked.
 *
 * Why it exists: a short secret (`true`, a PIN, `cafe`) also occurs inside a URI, an id or a hash, and masking there makes the answer unusable (`runUri`, `continueArguments`) or fails a saved study's checks, while these fields never hold learner text. It is the one rule of which fields are identifiers; called by {@link maskRunSecretsDeep} for every property it walks.
 * @param key - The property name.
 * @param value - The property value.
 * @returns `true` for a generated-value key, or an identifier key holding a string or an array of strings.
 * @example
 * isGeneratedIdentifier('runUri', 'codebook://runs/true-1') // => true
 */
function isGeneratedIdentifier(key: string, value: unknown): boolean {
  if (GENERATED_VALUE_KEYS.has(key)) return true
  if (!IDENTIFIER_KEY.test(key)) return false
  return (
    typeof value === 'string' ||
    (Array.isArray(value) && value.every((entry) => typeof entry === 'string'))
  )
}

/**
 * Keeps an identifier's bytes unless it is exactly a secret.
 *
 * Why it exists: `{ apiKey: '<secret>' }` is learner text under an identifier-shaped key; only a secret merely inside an identifier is exempt. Called by {@link maskRunSecretsDeep} for each identifier property.
 * @param value - A string, an array of strings, or a generated-value object under an identifier key.
 * @param secrets - The run-scoped secret values.
 * @returns The value with each string that equals a secret replaced by the mask; other values unchanged.
 * @example
 * keepIdentifier(['x', 'hunter2'], new Set(['hunter2'])) // => ['x', '[masked]']
 */
function keepIdentifier(value: unknown, secrets: ReadonlySet<string>): unknown {
  if (typeof value === 'string')
    return secrets.has(value) ? REDACTION_MASK : value
  if (Array.isArray(value))
    return value.map((entry) => keepIdentifier(entry, secrets))
  // A generated-value key holds an object that is kept whole.
  return value
}

/**
 * Replaces every exact occurrence of each run secret in a text by the redaction mask.
 *
 * Why it exists: a value the learner typed through ask-learner has no recognizable shape, so a copy of it in a preview, an error message or a log can only be hidden by its value (ENG-4). Called by every serialization of a run (inspection values, debugger previews, errors, MCP results, saved studies) through {@link maskRunSecretsDeep}.
 * @param text - Any text that may hold a copy of a secret.
 * @param secrets - The run-scoped secret values; empty strings are ignored.
 * @returns The text with each secret replaced; the longest secret is replaced first.
 * @example
 * maskRunSecrets('failed for hunter2', new Set(['hunter2'])) // => 'failed for [masked]'
 */
export function maskRunSecrets(
  text: string,
  secrets: ReadonlySet<string>,
): string {
  let masked = text
  for (const secret of orderedSecrets(secrets))
    masked = masked.split(secret).join(REDACTION_MASK)
  return masked
}

/**
 * Masks the run secrets in every string of a JSON-like value.
 *
 * Why it exists: results, snapshots and saved records are nested objects and arrays; this walks them once. Keys are never masked (protocol keys such as `status` must survive a secret that equals one; runtime data is stored as values). A property that {@link isGeneratedIdentifier} names keeps its value.
 * @param value - A JSON-like value: string, number, boolean, null, array or plain object.
 * @param secrets - The run-scoped secret values; empty strings are ignored.
 * @param keep - Says for an object (not an array) whether it is returned as it is, unmasked: for a record whose text is bound by a hash (a sealed source), where masking would break the seal.
 * @returns A copy with each string value masked; non-string leaves are returned as they are.
 * @example
 * maskRunSecretsDeep({ items: ['a hunter2 b'] }, new Set(['hunter2'])) // => { items: ['a [masked] b'] }
 */
export function maskRunSecretsDeep<T>(
  value: T,
  secrets: ReadonlySet<string>,
  keep?: (record: object) => boolean,
): T {
  return maskValue(value, secrets, orderedSecrets(secrets), keep) as T
}

function maskValue(
  value: unknown,
  secrets: ReadonlySet<string>,
  ordered: readonly string[],
  keep: ((record: object) => boolean) | undefined,
): unknown {
  if (typeof value === 'string')
    return ordered.length ? maskRunSecrets(value, secrets) : value
  if (Array.isArray(value))
    return value.map((entry) => maskValue(entry, secrets, ordered, keep))
  if (value !== null && typeof value === 'object' && keep?.(value)) return value
  if (value !== null && typeof value === 'object')
    return Object.fromEntries(
      Object.entries(value).map(([key, entry]) => [
        // Keys are never masked: Codebook's schemas fix them, and runtime data is stored as values and previews, not as keys.
        key,
        // Generated identifiers keep their bytes; everything else is masked.
        isGeneratedIdentifier(key, entry)
          ? keepIdentifier(entry, secrets)
          : maskValue(entry, secrets, ordered, keep),
      ]),
    )
  return value
}
